-- Recovery reverses only the actually recovered expense/asset amount. The
-- independent observed return already recorded the real processor cash.
CREATE TABLE public.provider_dispute_loss_recoveries(
 academy_id uuid NOT NULL,id uuid NOT NULL,loss_id uuid NOT NULL,collection_id uuid NOT NULL,dispute_id text NOT NULL,recovery_no integer NOT NULL CHECK(recovery_no BETWEEN 1 AND 1000),amount_minor numeric NOT NULL CHECK(amount_minor>0 AND amount_minor=trunc(amount_minor) AND amount_minor<1e38),posted_on date NOT NULL,source jsonb NOT NULL,approval_id uuid NOT NULL,created_by uuid NOT NULL,reason text NOT NULL CHECK(length(btrim(reason)) BETWEEN 1 AND 2000),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(academy_id,id),UNIQUE(academy_id,loss_id,recovery_no),FOREIGN KEY(academy_id,loss_id) REFERENCES public.provider_dispute_losses(academy_id,id),FOREIGN KEY(academy_id,collection_id) REFERENCES public.provider_collections(academy_id,id),FOREIGN KEY(academy_id,approval_id) REFERENCES public.approval_requests(academy_id,id),FOREIGN KEY(academy_id,created_by) REFERENCES public.people(academy_id,id),FOREIGN KEY(academy_id,id) REFERENCES public.finance_journals(academy_id,id) DEFERRABLE INITIALLY DEFERRED
);
CREATE INDEX provider_dispute_recovery_window ON public.provider_dispute_loss_recoveries(academy_id,posted_on,id);
CREATE INDEX provider_dispute_recovery_collection ON public.provider_dispute_loss_recoveries(collection_id,posted_on,id);
ALTER TABLE public.provider_dispute_loss_recoveries ENABLE ROW LEVEL SECURITY;ALTER TABLE public.provider_dispute_loss_recoveries FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_boundary ON public.provider_dispute_loss_recoveries USING(academy_id=nullif(current_setting('app.academy_id',true),'')::uuid) WITH CHECK(academy_id=nullif(current_setting('app.academy_id',true),'')::uuid);
CREATE TRIGGER finance_book_write BEFORE INSERT OR UPDATE OR DELETE ON public.provider_dispute_loss_recoveries FOR EACH STATEMENT EXECUTE FUNCTION public.guard_finance_book_write();
GRANT SELECT,INSERT ON public.provider_dispute_loss_recoveries TO kavosh_runtime;
-- Retain existing function identities;self-exclusion verifies the exact proof
-- at deferred completion without subtracting a different financial edition.
DO $$ DECLARE d text;needle text;replacement text;BEGIN
 d=pg_get_functiondef('public.provider_dispute_resolution_basis(uuid,date,uuid)'::regprocedure);
 d=regexp_replace(d,'^CREATE OR REPLACE FUNCTION [^\n]+','CREATE OR REPLACE FUNCTION public.provider_dispute_resolution_basis(p_collection uuid,p_on date,p_exclude_loss uuid,p_exclude_recovery uuid)');
 needle='BEGIN';replacement=$q$BEGIN IF(SELECT count(*) FROM public.provider_dispute_loss_recoveries WHERE collection_id=p_collection)>1000 THEN RETURN jsonb_build_object('unavailable','DISPUTE_RESOLUTION_REQUIRES_BACKGROUND');END IF;$q$;d=replace(d,needle,replacement);
 needle=$q$ ) asset_facts GROUP BY$q$;replacement=$r$ UNION ALL SELECT r.dispute_id,l.disputed_account::text,r.source->>'currencyId',r.source->>'currencyCode',(r.source->>'unitScale')::integer,r.amount_minor FROM public.provider_dispute_loss_recoveries r JOIN public.provider_dispute_losses l ON l.academy_id=r.academy_id AND l.id=r.loss_id WHERE r.academy_id=c.academy_id AND r.collection_id=c.id AND r.posted_on<=c.on_day AND(p_exclude_recovery IS NULL OR r.id<>p_exclude_recovery)
 ) asset_facts GROUP BY$r$;IF strpos(d,needle)=0 THEN RAISE EXCEPTION 'RECOVERY_ASSET_BASE_CHANGED';END IF;d=replace(d,needle,replacement);
 needle=$q$ ) b;
 source=jsonb_build_object$q$;replacement=$r$ UNION ALL SELECT 'loss_recovery',r.id,to_jsonb(r) FROM public.provider_dispute_loss_recoveries r WHERE r.academy_id=c.academy_id AND r.collection_id=c.id AND(p_exclude_recovery IS NULL OR r.id<>p_exclude_recovery)
 ) b;
 source=jsonb_build_object$r$;IF strpos(d,needle)=0 THEN RAISE EXCEPTION 'RECOVERY_BOOK_BASE_CHANGED';END IF;d=replace(d,needle,replacement);
 needle=$q$'cases',case_rows,'movements',movement_rows$q$;replacement=$r$'lossRecoveries',coalesce((SELECT jsonb_agg(jsonb_build_object('id',r.id,'lossId',r.loss_id,'disputeId',r.dispute_id,'postedOn',r.posted_on::text,'amountMinor',trunc(r.amount_minor)::text,'currencyId',r.source->'currencyId','currencyCode',r.source->'currencyCode','unitScale',r.source->'unitScale','recoveryNo',r.recovery_no) ORDER BY r.id) FROM public.provider_dispute_loss_recoveries r WHERE r.academy_id=c.academy_id AND r.collection_id=c.id AND r.posted_on<=c.on_day AND(p_exclude_recovery IS NULL OR r.id<>p_exclude_recovery)),'[]'::jsonb),'cases',case_rows,'movements',movement_rows$r$;IF strpos(d,needle)=0 THEN RAISE EXCEPTION 'RECOVERY_PROJECTION_BASE_CHANGED';END IF;EXECUTE replace(d,needle,replacement);
 d=pg_get_functiondef('public.provider_dispute_loss_recovery_source(uuid,date)'::regprocedure);d=regexp_replace(d,'^CREATE OR REPLACE FUNCTION [^\n]+','CREATE OR REPLACE FUNCTION public.provider_dispute_loss_recovery_basis(p_loss uuid,p_on date,p_exclude uuid)');
 d=replace(d,'amount numeric;proof jsonb;','amount numeric;prior numeric;edition integer;proof jsonb;');
 needle='s=public.provider_dispute_resolution_source(c.id,p_on);';replacement=$q$SELECT coalesce(sum(amount_minor),0),coalesce(max(recovery_no),0) INTO prior,edition FROM public.provider_dispute_loss_recoveries WHERE academy_id=l.academy_id AND loss_id=l.id AND(p_exclude IS NULL OR id<>p_exclude);IF edition>=1000 OR EXISTS(SELECT 1 FROM public.provider_dispute_loss_recoveries WHERE academy_id=l.academy_id AND loss_id=l.id AND posted_on>p_on AND(p_exclude IS NULL OR id<>p_exclude)) THEN RETURN NULL;END IF;s=public.provider_dispute_resolution_basis(c.id,p_on,NULL,p_exclude);$q$;IF strpos(d,needle)=0 THEN RAISE EXCEPTION 'RECOVERY_SOURCE_BASE_CHANGED';END IF;d=replace(d,needle,replacement);
 d=replace(d,'amount>l.amount_minor','amount>l.amount_minor-prior');d=replace(d,'l.amount_minor-amount','l.amount_minor-prior-amount');
 d=replace(d,$q$'version',1,'lossId',l.id$q$,$r$'version',2,'expectedVersion',edition,'previouslyRecoveredMinor',trunc(prior)::text,'lossId',l.id$r$);
 d=replace(d,$q$RETURN jsonb_build_object('lossId',l.id$q$,$r$RETURN jsonb_build_object('expectedVersion',edition,'previouslyRecoveredMinor',trunc(prior)::text,'lossId',l.id$r$);EXECUTE d;
END $$;
CREATE OR REPLACE FUNCTION public.provider_dispute_resolution_basis(p_collection uuid,p_on date,p_exclude_loss uuid) RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog SET DateStyle='ISO,YMD' AS $$ SELECT public.provider_dispute_resolution_basis(p_collection,p_on,p_exclude_loss,NULL) $$;
CREATE OR REPLACE FUNCTION public.provider_dispute_loss_recovery_source(p_loss uuid,p_on date) RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog SET DateStyle='ISO,YMD' AS $$ SELECT public.provider_dispute_loss_recovery_basis(p_loss,p_on,NULL) $$;
CREATE FUNCTION public.guard_provider_dispute_loss_recovery() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog SET DateStyle='ISO,YMD' AS $$ DECLARE l record;c record;p record;s jsonb;BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'PROVIDER_DISPUTE_RECOVERY_IMMUTABLE' USING ERRCODE='23514';END IF;
 SELECT * INTO l FROM public.provider_dispute_losses WHERE academy_id=NEW.academy_id AND id=NEW.loss_id;SELECT * INTO c FROM public.provider_collections WHERE academy_id=NEW.academy_id AND id=l.collection_id;
 PERFORM public.lock_customer_credit(c.id);PERFORM public.lock_collector_funds(c.collector_id,c.holding_account);PERFORM id FROM public.tuition_invoices WHERE academy_id=NEW.academy_id AND id=c.invoice_id FOR UPDATE;PERFORM pg_advisory_xact_lock(hashtextextended(NEW.academy_id::text||':checkout-provider:'||c.account_id,0));
 s=public.provider_dispute_loss_recovery_source(l.id,NEW.posted_on);SELECT * INTO p FROM public.approval_requests WHERE academy_id=NEW.academy_id AND id=NEW.approval_id;
 IF s IS NULL OR NEW.collection_id IS DISTINCT FROM c.id OR NEW.dispute_id IS DISTINCT FROM l.dispute_id OR NEW.recovery_no IS DISTINCT FROM(s->>'expectedVersion')::integer+1 OR NEW.source IS DISTINCT FROM s OR NEW.amount_minor IS DISTINCT FROM(s->>'amountMinor')::numeric OR p.id IS NULL OR p.action IS DISTINCT FROM 'finance.provider-dispute.recover-loss' OR p.status IS DISTINCT FROM 'pending' OR p.target_id IS DISTINCT FROM NEW.id OR p.target_version<>0 OR p.privacy_capability IS DISTINCT FROM 'dispute-losses.view' OR p.review_context->'source' IS DISTINCT FROM s
 OR p.payload IS DISTINCT FROM jsonb_build_object('lossId',NEW.loss_id,'collectionId',NEW.collection_id,'expectedVersion',s->'expectedVersion','sourceStamp',s->'sourceStamp','postedOn',NEW.posted_on::text,'period',p.payload->'period','reason',NEW.reason)
 OR p.scope->'recordContext' IS DISTINCT FROM jsonb_build_object('hubId',c.hub_id,'classId',c.class_id,'studentId',c.student_id) OR NOT public.report_comment_human_verified(NEW.created_by) OR NOT EXISTS(SELECT 1 FROM public.academies WHERE id=NEW.academy_id AND status='active') THEN RAISE EXCEPTION 'PROVIDER_DISPUTE_RECOVERY_SOURCE_REQUIRED' USING ERRCODE='23514';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.academies WHERE id=NEW.academy_id AND master_person_id=NEW.created_by) AND(p.requester_id=NEW.created_by OR NOT public.is_supervisor(NEW.created_by,p.requester_id) OR c.student_id=NEW.created_by OR EXISTS(SELECT 1 FROM public.family_relationships WHERE academy_id=NEW.academy_id AND student_id=c.student_id AND guardian_id=NEW.created_by) OR EXISTS(SELECT 1 FROM public.finance_collectors WHERE academy_id=NEW.academy_id AND id=c.collector_id AND person_id=NEW.created_by)) THEN RAISE EXCEPTION 'PROVIDER_DISPUTE_RECOVERY_UPPER_REQUIRED' USING ERRCODE='23514';END IF;RETURN NEW;
END $$;
CREATE TRIGGER provider_dispute_loss_recovery BEFORE INSERT OR UPDATE OR DELETE ON public.provider_dispute_loss_recoveries FOR EACH ROW EXECUTE FUNCTION public.guard_provider_dispute_loss_recovery();
CREATE FUNCTION public.complete_provider_dispute_loss_recovery() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog SET DateStyle='ISO,YMD' AS $$ DECLARE p record;j record;actual jsonb;BEGIN
 SELECT * INTO p FROM public.approval_requests WHERE academy_id=NEW.academy_id AND id=NEW.approval_id;SELECT * INTO j FROM public.finance_journals WHERE academy_id=NEW.academy_id AND id=NEW.id;
 SELECT jsonb_agg(jsonb_build_object('accountId',account_id,'accountVersion',account_version,'side',side,'amountMinor',trunc(amount_minor)::text) ORDER BY line_number) INTO actual FROM public.finance_journal_lines WHERE academy_id=NEW.academy_id AND journal_id=NEW.id;
 IF NEW.source IS DISTINCT FROM public.provider_dispute_loss_recovery_basis(NEW.loss_id,NEW.posted_on,NEW.id) OR p.status IS DISTINCT FROM 'applied' OR p.reviewer_id IS DISTINCT FROM NEW.created_by OR j.id IS NULL OR j.approval_id IS DISTINCT FROM NEW.approval_id OR j.posted_by IS DISTINCT FROM NEW.created_by OR j.posted_on IS DISTINCT FROM NEW.posted_on OR j.purpose IS DISTINCT FROM 'activity' OR j.reverses_id IS NOT NULL OR j.line_count<>2 OR actual IS DISTINCT FROM NEW.source->'lines' OR j.reference IS DISTINCT FROM 'provider-dispute-loss-recovery:'||NEW.id::text OR j.period_id IS DISTINCT FROM(p.payload#>>'{period,id}')::uuid OR j.period_version IS DISTINCT FROM(p.payload#>>'{period,version}')::integer
 OR NOT EXISTS(SELECT 1 FROM public.audit_events WHERE academy_id=NEW.academy_id AND entity_id=NEW.id AND actor_id=NEW.created_by AND created_at=transaction_timestamp() AND action='finance.provider-dispute.loss-recovered' AND changes=jsonb_build_object('approvalId',NEW.approval_id,'collectionId',NEW.collection_id,'lossId',NEW.loss_id,'severity','critical','customerCreditChanged',false,'cashMovementPerformed',false,'providerOperationPerformed',false)) THEN RAISE EXCEPTION 'PROVIDER_DISPUTE_RECOVERY_INCOMPLETE' USING ERRCODE='23514';END IF;RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER provider_dispute_loss_recovery_complete AFTER INSERT ON public.provider_dispute_loss_recoveries DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.complete_provider_dispute_loss_recovery();
CREATE FUNCTION public.provider_dispute_loss_recovery_effect() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN IF NEW.action='finance.provider-dispute.recover-loss' AND NEW.status='applied' AND NOT EXISTS(SELECT 1 FROM public.provider_dispute_loss_recoveries WHERE academy_id=NEW.academy_id AND id=NEW.target_id AND approval_id=NEW.id AND created_by=NEW.reviewer_id) THEN RAISE EXCEPTION 'PROVIDER_DISPUTE_RECOVERY_EFFECT_REQUIRED' USING ERRCODE='23514';END IF;RETURN NULL;END $$;
CREATE CONSTRAINT TRIGGER provider_dispute_loss_recovery_effect AFTER INSERT OR UPDATE ON public.approval_requests DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.provider_dispute_loss_recovery_effect();
CREATE FUNCTION public.provider_dispute_loss_recovery_privacy() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE l record;c record;bindings jsonb;hubs uuid[];BEGIN
 SELECT * INTO l FROM public.provider_dispute_losses WHERE academy_id=NEW.academy_id AND id=(NEW.payload->>'lossId')::uuid;SELECT * INTO c FROM public.provider_collections WHERE academy_id=NEW.academy_id AND id=l.collection_id;
 SELECT coalesce(jsonb_agg(DISTINCT b.value),'[]'::jsonb) INTO bindings FROM public.approval_requests p CROSS JOIN LATERAL jsonb_array_elements(p.privacy_bindings) b WHERE p.academy_id=NEW.academy_id AND(p.id=l.approval_id OR p.id IN(SELECT approval_id FROM public.provider_dispute_postings WHERE academy_id=NEW.academy_id AND collection_id=c.id) OR p.id IN(SELECT x.approval_id FROM public.provider_dispute_corrections x JOIN public.provider_dispute_postings d ON d.academy_id=x.academy_id AND d.id=x.posting_id WHERE d.academy_id=NEW.academy_id AND d.collection_id=c.id) OR p.id IN(SELECT approval_id FROM public.provider_dispute_loss_recoveries WHERE academy_id=NEW.academy_id AND collection_id=c.id));
 IF jsonb_array_length(bindings)>60 THEN RAISE EXCEPTION 'DISPUTE_RECOVERY_PRIVACY_REQUIRES_BACKGROUND' USING ERRCODE='23514';END IF;
 SELECT array_agg(hub_id ORDER BY id) INTO hubs FROM public.finance_accounts WHERE academy_id=NEW.academy_id AND id IN(c.credit_account,c.holding_account,l.disputed_account,l.expense_account);NEW.privacy_bindings=NEW.privacy_bindings||bindings||jsonb_build_array(public.approval_hub_binding('accounts.view',hubs),public.approval_hub_binding('journals.view',hubs));RETURN NEW;
END $$;
CREATE TRIGGER zz_provider_dispute_loss_recovery_privacy BEFORE INSERT ON public.approval_requests FOR EACH ROW WHEN(NEW.action='finance.provider-dispute.recover-loss') EXECUTE FUNCTION public.provider_dispute_loss_recovery_privacy();
CREATE FUNCTION public.provider_dispute_loss_recovery_journal_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN
 IF NEW.reverses_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.provider_dispute_loss_recoveries WHERE academy_id=NEW.academy_id AND id=NEW.reverses_id) THEN RAISE EXCEPTION 'PROVIDER_DISPUTE_RECOVERY_CORRECTION_REQUIRED' USING ERRCODE='23514';END IF;
 IF public.provider_transaction_reference(NEW.reference) LIKE 'provider-dispute-loss-recovery:%' AND NOT EXISTS(SELECT 1 FROM public.provider_dispute_loss_recoveries WHERE academy_id=NEW.academy_id AND id=NEW.id AND approval_id=NEW.approval_id AND public.provider_transaction_reference(NEW.reference)='provider-dispute-loss-recovery:'||id::text) THEN RAISE EXCEPTION 'PROVIDER_DISPUTE_RECOVERY_SOURCE_REQUIRED' USING ERRCODE='23514';END IF;RETURN NEW;
END $$;
CREATE TRIGGER provider_dispute_loss_recovery_journal BEFORE INSERT ON public.finance_journals FOR EACH ROW EXECUTE FUNCTION public.provider_dispute_loss_recovery_journal_guard();
DO $$ DECLARE d text;needle text;BEGIN
 d=pg_get_viewdef('public.provider_cost_events'::regclass,true);EXECUTE 'CREATE OR REPLACE VIEW public.provider_cost_events WITH(security_invoker=true) AS '||rtrim(d,E';\n ')||' UNION ALL SELECT academy_id,id,collection_id,approval_id,posted_on,-amount_minor,source FROM public.provider_dispute_loss_recoveries';
 d=pg_get_functiondef('public.provider_dispute_release_basis(uuid,date)'::regprocedure);needle=$q$ ) b;
 stamp=encode$q$;IF strpos(d,needle)=0 THEN RAISE EXCEPTION 'RECOVERY_RELEASE_BOOK_BASE_CHANGED';END IF;EXECUTE replace(d,needle,$r$ UNION ALL SELECT 'loss_recovery',r.id,to_jsonb(r) FROM public.provider_dispute_loss_recoveries r WHERE r.academy_id=c.academy_id AND r.collection_id=c.id
 ) b;
 stamp=encode$r$);
 d=pg_get_functiondef('public.provider_dispute_release_privacy()'::regprocedure);needle=$q$collection_id=(NEW.payload->>'collectionId')::uuid))) unique_bindings$q$;IF strpos(d,needle)=0 THEN RAISE EXCEPTION 'RECOVERY_RELEASE_PRIVACY_BASE_CHANGED';END IF;EXECUTE replace(d,needle,$r$collection_id=(NEW.payload->>'collectionId')::uuid) OR p.id IN(SELECT approval_id FROM public.provider_dispute_loss_recoveries WHERE academy_id=NEW.academy_id AND collection_id=(NEW.payload->>'collectionId')::uuid))) unique_bindings$r$);
END $$;
REVOKE ALL ON FUNCTION public.provider_dispute_resolution_basis(uuid,date,uuid,uuid),public.provider_dispute_loss_recovery_basis(uuid,date,uuid),public.guard_provider_dispute_loss_recovery(),public.complete_provider_dispute_loss_recovery(),public.provider_dispute_loss_recovery_effect(),public.provider_dispute_loss_recovery_privacy(),public.provider_dispute_loss_recovery_journal_guard() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.provider_dispute_resolution_basis(uuid,date,uuid,uuid),public.provider_dispute_loss_recovery_basis(uuid,date,uuid) TO kavosh_runtime;
CREATE OR REPLACE FUNCTION public.schema_revision() RETURNS integer LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT 338 $$;
